    explicit Fixture(unsigned rate=48000,unsigned block=128,bool onlyGain=false){app->new_project(rate,"Private binding fixture / no hardware");track=app->add_audio_track("Binding input");app->set_track_input(track,0);app->set_track_monitoring(track,true);gain.id=new_id();filter.id=new_id();filter.kind=InsertKind::highpass;rig.id=new_id();rig.kind=InsertKind::rig;rig.rig.pre_fx={make_rig_module("mrs.compressor"),make_rig_module("mrs.drive")};app->set_inserts(track,onlyGain?std::vector<NativeInsert>{gain}:std::vector<NativeInsert>{gain,filter,rig});auto driver=std::make_unique<ManualDevice>();device=driver.get();app->connect(std::move(driver),{0,rate,block,{0},{0,1}});std::weak_ptr<desktop::Application> weak=app;host=std::make_shared<MRNativeParameterHost>([weak]{return weak.lock().get();});}
    NativeParameterKey key(std::uint32_t param=0)const{return {track,gain.id,{},param};}
    NativeInsert current(const Id& id)const{const auto p=app->services().projects->state().project;for(const auto& t:p->tracks)if(t.id==track)for(const auto& fx:t.inserts)if(fx.id==id)return fx;throw std::runtime_error("Missing fixture insert");}
    std::vector<NativeInsert> chain()const{for(const auto& t:app->services().projects->state().project->tracks)if(t.id==track)return t.inserts;return {};}
    float pump(unsigned frames=128){std::array<float,2048> input{},output{};input.fill(.25f);app->engine()->process(input.data(),output.data(),frames);return output[frames*2-1];}
